WITH filtered_customers AS (SELECT * FROM customers WHERE signup_date > '2025-09-01' OR signup_date <= '2023-05-05'), summary AS (SELECT CASE WHEN age >= 72 THEN 'high' WHEN age >= 43 THEN 'mid' ELSE 'low' END AS age_bucket, COUNT(CASE WHEN segment = 'Corporate' THEN 1 END) AS corporate_count FROM filtered_customers GROUP BY CASE WHEN age >= 72 THEN 'high' WHEN age >= 43 THEN 'mid' ELSE 'low' END) SELECT * FROM summary WHERE corporate_count < 6 ORDER BY 2 DESC, 1 DESC;
